package me.jackstar.drakescrates.oracle;

import me.jackstar.drakescraft.utils.MessageUtils; import org.bukkit.Bukkit; import org.bukkit.OfflinePlayer; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class OraculoCommand implements CommandExecutor {
 private final OracleService service;private final OracleYamlRepository relicaries;private final OracleGuiService gui;private final Runnable reload;
 public OraculoCommand(OracleService service,OracleYamlRepository relicaries,OracleGuiService gui,Runnable reload){this.service=service;this.relicaries=relicaries;this.gui=gui;this.reload=reload;}
 public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(args.length==0){if(sender instanceof Player p)gui.open(p);else MessageUtils.send(sender,"<red>Usa /oraculo givekey desde consola.");return true;}if("reclamar".equalsIgnoreCase(args[0])){MessageUtils.send(sender,"<yellow>Las recompensas se entregan al terminar cada vaticinio; las pendientes se entregan al reconectar.");return true;}if(!sender.hasPermission("drakescrates.admin")){MessageUtils.send(sender,"<red>Sin permiso.");return true;}try{if("reload".equalsIgnoreCase(args[0])){reload.run();MessageUtils.send(sender,"<green>Oráculo recargado.");return true;}if(args.length<4){MessageUtils.send(sender,"<red>/oraculo givekey|takekey|setpity <jugador> <relicario> <cantidad>");return true;}OfflinePlayer target=Bukkit.getOfflinePlayer(args[1]);String relicary=args[2].toLowerCase(Locale.ROOT);int amount=Integer.parseInt(args[3]);if(relicaries.get(relicary)==null)throw new IllegalArgumentException("Relicario desconocido");switch(args[0].toLowerCase(Locale.ROOT)){case "givekey"->service.give(target.getUniqueId(),relicary,amount);case "takekey"->{if(!service.take(target.getUniqueId(),relicary,amount))throw new IllegalArgumentException("Saldo insuficiente");}case "setpity"->service.setPity(target.getUniqueId(),relicary,amount);default->{MessageUtils.send(sender,"<red>Acción desconocida.");return true;}}MessageUtils.send(sender,"<green>Oráculo actualizado para <yellow>"+target.getName()+"</yellow>.");}catch(Exception ex){MessageUtils.send(sender,"<red>"+ex.getMessage()+"</red>");}return true;}
}
